export const invokeDeepSeek = async (messages: DeepSeekMessage[]): Promise<DeepSeekResponse> => {
  const config = loadConfig();

  if (config.deepseek.mock) {
    return {
      choices: [
        {
          message: {
            role: 'assistant',
            content: '故事继续：\n1. 继续追踪线索\n2. 与同伴讨论\n3. 查询线索\n4. 结束调查'
          }
        }
      ]
    };
  }

  const retries = Math.max(0, config.deepseek.maxRetries);
  const timeoutMs = Math.max(1000, config.deepseek.timeoutMs);

  for (let attempt = 0; attempt <= retries; attempt++) {
    const controller = new AbortController();
    const timeoutId = setTimeout(() => controller.abort(), timeoutMs);

    try {
      const response = await fetch(`${config.deepseek.baseUrl}/chat/completions`, {
        method: 'POST',
        headers: {
          'content-type': 'application/json',
          authorization: `Bearer ${config.deepseek.apiKey}`
        },
        body: JSON.stringify({
          model: config.deepseek.model,
          messages
        }),
        signal: controller.signal
      });

      clearTimeout(timeoutId);

      if (!response.ok) {
        throw new Error(`DeepSeek call failed: ${response.status}`);
      }

      const json = (await response.json()) as DeepSeekResponse;
      return json;
    } catch (error) {
      clearTimeout(timeoutId);
      const isAbortError = error instanceof Error && error.name === 'AbortError';

      if (attempt < retries) {
        if (isAbortError) {
          // brief backoff before retrying when the upstream times out
          await new Promise((resolve) => setTimeout(resolve, 200 * (attempt + 1)));
        }
        continue;
      }

      if (isAbortError) {
        throw new Error(`DeepSeek call timed out after ${timeoutMs}ms`);
      }

      throw error instanceof Error ? error : new Error('DeepSeek call failed');
    }
  }

  // Should be unreachable, loop either returns or throws.
  throw new Error('DeepSeek call failed');
};

