+const buildCompletionEndpoint = (baseUrl: string): string =>
+  `${baseUrl.replace(/\/$/, '')}/chat/completions`;
+
+interface ProviderRequestOptions {
+  providerName: string;
+  endpoint: string;
+  headers: Record<string, string>;
+  body: Record<string, unknown>;
+  timeoutMs: number;
+  maxRetries: number;
+}
+
+const requestWithRetries = async ({
+  providerName,
+  endpoint,
+  headers,
+  body,
+  timeoutMs,
+  maxRetries
+}: ProviderRequestOptions): Promise<Response> => {
+  const retries = Math.max(0, maxRetries);
+  const timeout = Math.max(1000, timeoutMs);
+
+  for (let attempt = 0; attempt <= retries; attempt++) {
+    const controller = new AbortController();
+    const timeoutId = setTimeout(() => controller.abort(), timeout);
+
+    try {
+      const response = await fetch(endpoint.replace(/\/$/, ''), {
+        method: 'POST',
+        headers: {
+          'content-type': 'application/json',
+          ...headers
+        },
+        body: JSON.stringify(body),
+        signal: controller.signal
+      });
+
+      clearTimeout(timeoutId);
+
+      if (!response.ok) {
+        throw new Error(`${providerName} call failed: ${response.status}`);
+      }
+
+      return response;
+    } catch (error) {
+      clearTimeout(timeoutId);
+      const isAbortError = error instanceof Error && error.name === 'AbortError';
