+import { storage } from '../../utils/storage';
+
+const NIGHT_MODE_KEY = 'night-mode';
+const MODEL_KEY = 'preferred-model';
+
+Page({
+  data: {
+    favorites: [],
+    showProfileModal: false,
+    showFavoritesModal: false,
+    showSettingsModal: false,
+    nightMode: false,
